#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.Metas;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        #region 元数据
        public FragmentMetaList? GetFragmentMetaList(string nsp)
        {
            var modResource = GetModResource(nsp);
            if (modResource == null)
                return null;
            return modResource.FragmentMetaList;
        }
        #endregion

        #region 碎片渐变
        public FragmentMeta? GetFragmentMeta(NamespaceID id)
        {
            var meta = GetFragmentMetaList(id.SpaceName);
            if (meta == null)
                return null;
            foreach (var m in meta.metas)
            {
                if (m.ID == id.Path)
                    return m;
            }
            return null;
        }
        public Gradient? GetFragmentGradient(NamespaceID id)
        {
            var meta = GetFinalFragmentSource(id);
            if (meta == null)
                return null;
            return meta.GetGradient();
        }
        #endregion
    }
}
